import json, sqlite3, sys
sys.path.insert(0, "project")
import service
db = sqlite3.connect("file:data/portal.sqlite?mode=ro", uri=True)
now = service.as_version(db, None)
def z(stamp):
    return service.instant(stamp, "x").strftime("%Y-%m-%dT%H:%M:%SZ")
allok = True
for channel in "ABCD":
    held = {}
    for path in (f"input/vault/{channel}-closing-04.json", f"data/receipts-spring-{channel}-delta6.json"):
        for batch in json.load(open(path, encoding="utf-8")):
            for uid, row in batch["rows"].items():
                held[uid] = z(row["utc"])
    book = {r["uid"]: z(r["utc"]) for r in service.rows_as_of(db, channel, now)}
    same = held == book
    allok = allok and same
    print(channel, "held==book:", same)
    for uid in sorted(book):
        print(f"   {uid:26s} book {book[uid]}  held {held.get(uid)}")
print("ALL FOUR CHANNELS IN STEP:", allok)
